        out.append(max(sorted(votes), key=votes.get))
    return out


def choose_k(X_train, y_train, X_val, y_val, ks):
    if not ks or not X_val or len(X_val) != len(y_val):
        raise ValueError('need candidate ks and labelled validation rows')
    scores = {}
    for k in ks:
        pred = knn_predict(X_train, y_train, X_val, k)
        scores[k] = sum(p == t for p, t in zip(pred, y_val)) / len(y_val)
    best = min(scores, key=lambda k: (-scores[k], k))
    return {'scores': scores, 'best': best}

